func testCustoOperacionalToManyAddOpCopCustoOperacionalProdutos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a CustoOperacional
	var b, c, d, e CustoOperacionalProduto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, custoOperacionalDBTypes, false, strmangle.SetComplement(custoOperacionalPrimaryKeyColumns, custoOperacionalColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*CustoOperacionalProduto{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, custoOperacionalProdutoDBTypes, false, strmangle.SetComplement(custoOperacionalProdutoPrimaryKeyColumns, custoOperacionalProdutoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*CustoOperacionalProduto{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddCopCustoOperacionalProdutos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.CopID != first.CopID {
			t.Error("foreign key was wrong value", a.CopID, first.CopID)
		}
		if a.CopID != second.CopID {
			t.Error("foreign key was wrong value", a.CopID, second.CopID)
		}

		if first.R.Cop != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Cop != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.CopCustoOperacionalProdutos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.CopCustoOperacionalProdutos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.CopCustoOperacionalProdutos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

